pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // The entry point is AdjustBetAmounts; we call it as the caller (not the owner)
        vm.prank(caller);
        c.AdjustBetAmounts(amount);

        // Now attempt to open to the public as the same non-owner caller.
        // In the reference contract this reverts; in the buggy version it succeeds.
        bool ref_ok;
        try c.OpenToThePublic() { ref_ok = true; } catch { ref_ok = false; }

        // General rule: after a non-owner calls AdjustBetAmounts, the same non-owner cannot toggle openToPublic to true
        // i.e. the call to OpenToThePublic must revert.
        assertTrue(!ref_ok);
    }
}

